namespace Sunplus.Agent.Model.BL.MemberInfo.CreditBalance
{
    using System.Collections;
    using System.Data;
    using Sunplus.Agent.Model.BL.Definitions;
    using Sunplus.Agent.Model.DL.MemberInfo.CreditBalance;

    public class CreditBalanceBO : Sunplus.Agent.Model.BL.Base.BOBase
    {
        private static readonly CreditBalanceDAO dao = new CreditBalanceDAO();

        public CreditBalanceBO(string netSessionId)
            : base(netSessionId)
        {
        }

        /// <summary>
        /// Clear credit of a customer.
        /// </summary>
        /// <param name="custId">Id of customer</param>
        /// <param name="ip">Login ip address</param>
        /// <param name="errorMsg">Output error message</param>
        /// <returns>Return error code, success=0</returns>
        public int ClearCustomerCredit(int custId, string ip, out string errorMsg)
        {
            return dao.Age_CustomerUpdClearCredit(custId, CurrentSession.SubAccId, CurrentSession.UserId, ip, CurrentSession.LangKey, out errorMsg);
        }

        /// <summary>
        /// Get credit information of current customer.
        /// </summary>
        /// <returns></returns>
        public Hashtable GetCreditBalance()
        {
            int custId = CurrentSession.CustId;
            int roleId = CurrentSession.RoleId;
            if (roleId == (int)UserTypes.Agent)
            {
                return dao.Age_CustomerSelBalance_Ag(custId);
            }
            else if (roleId == (int)UserTypes.Master)
            {
                return dao.Age_CustomerSelBalance_Mag(custId);
            }
            else if (roleId == (int)UserTypes.Super)
            {
                return dao.Age_CustomerSelBalance_SAg(custId);
            }
            else
            {
                throw new BusinessException("Invalid role id for customer " + custId + ": " + roleId);
            }
        }

        public DataTable GetCreditBalanceListAg(int custId, string userName, int status, int pageIndex, int pageSize, ref int totalPages)
        {
            return dao.Age_CustomerSelCreditBalanceList_Ag(custId, userName, status, pageIndex, pageSize, ref totalPages);
        }

        public DataTable GetCreditBalanceListMag(int custId, string userName, int status, int pageIndex, int pageSize, ref int totalPages)
        {
            return dao.Age_CustomerSelCreditBalanceList_Mag(custId, userName, status, pageIndex, pageSize, ref totalPages);
        }

        public DataTable GetCreditBalanceListSag(int custId, string userName, int status, int pageIndex, int pageSize, ref int totalPages)
        {
            return dao.Age_CustomerSelCreditBalanceList_Sag(custId, userName, status, pageIndex, pageSize, ref totalPages);
        }

        public DataTable GetCreditBalanceListLCSWinLimit(int custId, string userName, int status, int pageIndex, int pageSize)
        {
            return dao.Age_CustomerSelWinLimitList_Ag(custId, userName, status, pageIndex, pageSize);
        }
    }
